CREATE TABLE IF NOT EXISTS justifications(id UUID PRIMARY KEY,absence_id UUID NOT NULL UNIQUE,volunteer_id UUID NOT NULL,reason TEXT NOT NULL,status VARCHAR(30) NOT NULL,submitted_at TIMESTAMP NOT NULL,resolution_comment TEXT); CREATE TABLE IF NOT EXISTS penalties(id UUID PRIMARY KEY,volunteer_id UUID NOT NULL,reason TEXT NOT NULL,starts_at DATE NOT NULL,ends_at DATE NOT NULL,status VARCHAR(30) NOT NULL);
